node -e "
const toRad = d => d * Math.PI / 180;

// Current device location (San Francisco)
const lat1 = 37.7749, lon1 = -122.4194;

// Boston, MA 02118 approximate coordinates
const lat2 = 42.3396, lon2 = -71.0693;

// Haversine formula
const R = 3958.8; // Earth radius in miles

const dlat = toRad(lat2 - lat1);
const dlon = toRad(lon2 - lon1);
const a = Math.sin(dlat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dlon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const distMiles = R * c;
const distKm = distMiles * 1.60934;

console.log('=== Distance Calculation ===');
console.log('From:  (37.7749°N, 122.4194°W) — Your location, San Francisco, CA');
console.log('To:    (42.3396°N, 71.0693°W)  — 4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distMiles.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
"
